<?php
declare(strict_types=1);
function customer_profile(int $id):array{return one('SELECT * FROM customer_profiles WHERE user_id=?',[$id])??['user_id'=>$id,'phone'=>'','default_address_id'=>null,'dietary_notes'=>''];}
function customer_default_address(int $id):?array{$profile=customer_profile($id);return $profile['default_address_id']?one('SELECT * FROM customer_addresses WHERE id=? AND user_id=?',[$profile['default_address_id'],$id]):null;}
function customer_address_text(array $address):string{return trim($address['address'].($address['city']!==''?"\n".$address['city']:''));}
function customer_safe_error(Throwable $error):string{return ($error instanceof InvalidArgumentException||get_class($error)===RuntimeException::class)?$error->getMessage():'This change could not be saved. Please try again.';}
function customer_action(string $action):never{
 $u=require_login();if($u['role']!=='customer')abort(403,'Use a customer account for this action.');$id=(int)$u['id'];$back='account';
 if($action==='wallet/refresh'){
  header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');rate_limit('wallet_auto:'.$id,8,300);
  $cursor=(int)($_SESSION['wallet_refresh_cursor']??0);$query="SELECT id,reference FROM wallet_topups WHERE user_id=? AND attempted=1 AND status='initialized' AND id>? ORDER BY id LIMIT 1";
  $pending=one($query,[$id,$cursor])??one($query,[$id,0]);$credited=false;$message='';
  if($pending){$_SESSION['wallet_refresh_cursor']=(int)$pending['id'];try{$credited=wallet_verify_topup($pending['reference']);}catch(Throwable $error){$message=customer_safe_error($error);}}
  echo json_encode(['credited'=>$credited,'mode'=>paystack_mode(),'balance'=>wallet_balance($id,paystack_mode()),'message'=>$message]);exit;
 }
 try{
  if($action==='profile'){$back='account/settings';$name=str('name',150);$phone=str('phone',60);if($name==='')throw new InvalidArgumentException('Enter your name.');db()->beginTransaction();sql('UPDATE users SET name=? WHERE id=?',[$name,$id]);sql('INSERT INTO customer_profiles(user_id,phone,dietary_notes) VALUES(?,?,?) ON DUPLICATE KEY UPDATE phone=VALUES(phone),dietary_notes=VALUES(dietary_notes)',[$id,$phone,str('dietary_notes',500)]);db()->commit();flash('Your profile is updated.');}
  elseif(in_array($action,['password','email'],true)){
   $back='account/settings';rate_limit('customer_security:'.$id,8,900);$current=$_POST[$action==='password'?'current-password':'email-current-password']??'';db()->beginTransaction();$account=one('SELECT * FROM users WHERE id=? FOR UPDATE',[$id]);if(!is_string($current)||!password_verify($current,$account['password']))throw new InvalidArgumentException('Your current password is incorrect.');
   $event='account:security:'.$id.':'.bin2hex(random_bytes(8));
   if($action==='password'){$password=$_POST['new_password']??'';if(!is_string($password)||mb_strlen($password)<10||strlen($password)>72||str_contains($password,"\0"))throw new InvalidArgumentException('Use at least 10 characters and avoid a very long password.');if(!is_string($_POST['password_confirm']??null)||!hash_equals($password,$_POST['password_confirm']))throw new InvalidArgumentException('The new passwords do not match.');sql('UPDATE users SET password=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$id]);email_queue_template('password_changed',$event,$account['email'],['name'=>$account['name']]);}
   else{$email=strtolower(str('email',190));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$email!==strtolower(str('email_confirm',190)))throw new InvalidArgumentException('Enter a valid email and repeat it exactly.');if(one('SELECT id FROM users WHERE email=? AND id<>?',[$email,$id]))throw new InvalidArgumentException('That email is already used by another account.');sql('UPDATE users SET email=? WHERE id=?',[$email,$id]);email_queue_template('account_email_changed',$event.':old',$account['email'],['name'=>$account['name']]);if($email!==$account['email'])email_queue_template('account_email_changed',$event.':new',$email,['name'=>$account['name']]);}
   sql('DELETE FROM account_reset_tokens WHERE user_id=?',[$id]);db()->commit();unset($_SESSION['uid'],$_SESSION['customer_auth_stamp'],$_SESSION['owner_auth_stamp'],$_SESSION['csrf']);session_regenerate_id(true);flash('Your sign-in details changed. Sign in again with your new details.');go('login');
  }
  elseif($action==='address/save'){
   $back='account/addresses';$addressId=(int)($_POST['id']??0);$values=[str('label',60),str('recipient',150),str('phone',60),str('address',1000),str('city',100),str('instructions',500)];if(!$values[0]||!$values[1]||!$values[2]||!$values[3])throw new InvalidArgumentException('Complete the address label, recipient, phone and address.');
   db()->beginTransaction();sql('INSERT IGNORE INTO customer_profiles(user_id) VALUES(?)',[$id]);one('SELECT user_id FROM customer_profiles WHERE user_id=? FOR UPDATE',[$id]);
   if($addressId){if(!one('SELECT id FROM customer_addresses WHERE id=? AND user_id=?',[$addressId,$id]))throw new InvalidArgumentException('Address not found.');sql('UPDATE customer_addresses SET label=?,recipient=?,phone=?,address=?,city=?,instructions=? WHERE id=? AND user_id=?',[...$values,$addressId,$id]);}
   else{if((int)one('SELECT COUNT(*) n FROM customer_addresses WHERE user_id=?',[$id])['n']>=5)throw new InvalidArgumentException('You can save up to five addresses.');sql('INSERT INTO customer_addresses(label,recipient,phone,address,city,instructions,user_id) VALUES(?,?,?,?,?,?,?)',[...$values,$id]);$addressId=(int)db()->lastInsertId();}
   $profile=customer_profile($id);if(isset($_POST['is_default'])||!$profile['default_address_id'])sql('UPDATE customer_profiles SET default_address_id=? WHERE user_id=?',[$addressId,$id]);db()->commit();flash('Address saved.');
  }
  elseif($action==='address/delete'){$back='account/addresses';$addressId=(int)($_POST['id']??0);db()->beginTransaction();sql('INSERT IGNORE INTO customer_profiles(user_id) VALUES(?)',[$id]);$profile=one('SELECT * FROM customer_profiles WHERE user_id=? FOR UPDATE',[$id]);sql('DELETE FROM customer_addresses WHERE id=? AND user_id=?',[$addressId,$id]);if((int)$profile['default_address_id']===$addressId){$next=one('SELECT id FROM customer_addresses WHERE user_id=? ORDER BY id LIMIT 1',[$id]);sql('UPDATE customer_profiles SET default_address_id=? WHERE user_id=?',[$next['id']??null,$id]);}db()->commit();flash('Address removed.');}
  elseif($action==='favourite'){$back='account/saved';$product=(int)($_POST['product_id']??0);if(($_POST['save']??'1')!=='0'&&!one('SELECT id FROM products WHERE id=? AND available=1',[$product]))throw new InvalidArgumentException('This meal is not available to save.');if(($_POST['save']??'1')==='0')sql('DELETE FROM customer_favourites WHERE user_id=? AND product_id=?',[$id,$product]);else sql('INSERT IGNORE INTO customer_favourites(user_id,product_id) VALUES(?,?)',[$id,$product]);flash('Saved meals updated.');}
  elseif($action==='favourites/import'){$back='account/saved';$ids=$_POST['ids']??[];if(!is_array($ids)||count($ids)>50)throw new InvalidArgumentException('Import up to 50 saved meals at a time.');foreach(array_unique(array_map('intval',$ids)) as $product)if($product>0&&one('SELECT id FROM products WHERE id=? AND available=1',[$product]))sql('INSERT IGNORE INTO customer_favourites(user_id,product_id) VALUES(?,?)',[$id,$product]);flash('Saved meals imported from this device.');}
  elseif($action==='order/update'){$order=(int)($_POST['order_id']??0);$back='account/orders/'.$order;db()->beginTransaction();$record=one('SELECT * FROM orders WHERE id=? AND user_id=? FOR UPDATE',[$order,$id]);if(!$record||$record['status']!=='pending'||$record['payment_status']!=='unpaid')throw new InvalidArgumentException('This order can no longer be edited directly. Message the team for help.');$address=str('address',1000);if($record['fulfillment']==='delivery'&&$address==='')throw new InvalidArgumentException('Enter a delivery address.');sql('UPDATE orders SET address=?,notes=? WHERE id=? AND user_id=?',[$address,str('notes',500),$order,$id]);db()->commit();flash('Your order details are updated.');}
  elseif($action==='order/cancel'){$order=(int)($_POST['order_id']??0);$back='account/orders/'.$order;$lock='thirtyvi:pay:order:'.$order;if((int)(one('SELECT GET_LOCK(?,5) ok',[$lock])['ok']??0)!==1)throw new RuntimeException('Payment is busy. Please wait.');try{db()->beginTransaction();$record=one('SELECT * FROM orders WHERE id=? AND user_id=? FOR UPDATE',[$order,$id]);if(!$record||$record['status']!=='pending'||$record['payment_status']!=='unpaid')throw new InvalidArgumentException('Please contact the team to review cancellation of this order.');if(one("SELECT id FROM payments WHERE entity_type='order' AND entity_id=? AND status='initialized'",[$order]))throw new InvalidArgumentException('A payment is already in progress. Contact the team before cancelling.');sql("UPDATE orders SET status='cancelled' WHERE id=?",[$order]);sql('DELETE FROM stock_reservations WHERE order_id=?',[$order]);sql("INSERT INTO order_status_events(order_id,status,actor_id) VALUES(?,'cancelled',?)",[$order,$id]);$event=(int)db()->lastInsertId();db()->commit();run_hook('order.status',['id'=>$order,'status'=>'cancelled','event_id'=>$event]);flash('Your unpaid order was cancelled.');}finally{sql('SELECT RELEASE_LOCK(?)',[$lock]);}}
  elseif($action==='request'){$back='account/returns';rate_limit('customer_request:'.$id,10,3600);$order=(int)($_POST['order_id']??0);if($order&&!one('SELECT id FROM orders WHERE id=? AND user_id=?',[$order,$id]))throw new InvalidArgumentException('Choose one of your own orders.');$kind=str('kind',20);$subject=str('subject',150);$message=str('message',3000);if(!in_array($kind,['refund','return','cancel','change','help'],true)||$subject===''||mb_strlen($message)<10)throw new InvalidArgumentException('Choose a request type, subject and a message of at least 10 characters.');sql('INSERT INTO customer_requests(user_id,order_id,kind,subject,message) VALUES(?,?,?,?,?)',[$id,$order?:null,$kind,$subject,$message]);flash('Your request is with our team. Refunds and returns require review.');}
  elseif($action==='welcome'){$back='account/settings';rate_limit('welcome_resend:'.$id,3,86400);$existing=one("SELECT id,status FROM email_queue WHERE event_key=? OR event_key LIKE ? ORDER BY id DESC LIMIT 1",['account:created:'.$id,'account:welcome_resend:'.$id.':%']);if($existing&&in_array($existing['status'],['pending','retry','sending'],true)){sql("UPDATE email_queue SET available_at=NOW() WHERE id=? AND status IN ('pending','retry')",[$existing['id']]);flash('Your welcome email is already queued. Please allow the delivery worker a minute.');}elseif(one('SELECT id FROM email_queue WHERE event_key=?',['account:welcome_resend:'.$id.':'.gmdate('YmdH')])){flash('A welcome email was already requested this hour. Check Spam/Junk or try again later.');}else{email_queue_template('account_created','account:welcome_resend:'.$id.':'.gmdate('YmdH'),$u['email'],['name'=>$u['name']]);flash('Welcome email queued again. Check your inbox and spam folder.');}}
  elseif($action==='wallet/new'){$back='account/wallet';$_SESSION['wallet_topup_nonce']=bin2hex(random_bytes(24));flash('New top-up form ready. Earlier payments can still be checked below.');}
  elseif($action==='wallet/topup'){$back='account/wallet';rate_limit('wallet_topup:'.$id,8,600);$url=wallet_start_topup($id,wallet_minor(str('amount',20)),str('nonce',64),str('mode',4));header('Location: '.$url);exit;}
  elseif($action==='wallet/verify'){$back='account/wallet';rate_limit('wallet_verify:'.$id,15,300);$reference=str('reference',80);if(!one('SELECT id FROM wallet_topups WHERE reference=? AND user_id=?',[$reference,$id]))throw new InvalidArgumentException('Top-up not found.');flash(wallet_verify_topup($reference)?'Top-up verified. Your wallet is updated.':'Payment is not yet verified. Please check again shortly.');}
  elseif($action==='wallet/pay'){$kind=str('kind',10);$entity=(int)($_POST['id']??0);$back='account/'.($kind==='booking'?'bookings':'orders').'/'.$entity;wallet_pay($id,$kind,$entity);flash('Payment completed from your wallet.');}
  else throw new InvalidArgumentException('Unknown account action.');
 }catch(Throwable $error){if(db()->inTransaction())db()->rollBack();flash(customer_safe_error($error),'error');}
 if(in_array($action,['favourite','favourites/import'],true)&&str_contains(strtolower((string)($_SERVER['HTTP_ACCEPT']??'')),'application/json')){$message=$_SESSION['flash']??[];unset($_SESSION['flash']);header('Content-Type: application/json');http_response_code(($message['type']??'')==='error'?422:200);echo json_encode(['ok'=>($message['type']??'')!=='error','message'=>$message['message']??'Saved']);exit;}
 go($back);
}
